<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Headphones, ArrowRight, FileText, Upload, Download, RefreshCw, LogOut, Info, Check, LoaderCircle, MessageSquareText, SlidersHorizontal } from 'lucide-vue-next';
import { ASPECTS, SENTIMENT_NAMES, type Analysis, type Product, type ProductStats, type Review, type ImportPreview, type Job, type AspectId, type ImportColumns, type ColumnMapping, type ProductSummary } from '../../../packages/contracts/index';
import { api, post, token, saveToken, download } from './api';
import AnalysisResult from './components/AnalysisResult.vue';
import ReviewList from './components/ReviewList.vue';
import ImportMapping from './components/ImportMapping.vue';
import ProductOverview from './components/ProductOverview.vue';
import PlatformCollection from './components/PlatformCollection.vue';
import AnalysisTasks, { type DataBatch } from './components/AnalysisTasks.vue';
const router=useRouter(); const route = useRoute(); const path = computed(() => route.path);
const products = ref<Product[]>([]); const model = ref<{ semantic: { ready: boolean; model: string; version: string; message: string }; version: string; algorithm: string; trainingExamples: number; dataKind: string; limitations: string[]; evaluation: { dataset: string; count: number; hybrid: { aspectMicroF1: number; pairMicroF1: number }; rules: { aspectMicroF1: number; pairMicroF1: number } } | null } | null>(null);
const error = ref(''); const notice = ref(''); const admin = ref(false); const busy = ref(false); const modelExpanded = ref(false);
const text = ref('音质很清晰，降噪效果不错。但戴久了耳朵疼，打游戏声音慢半拍。');
const examples = ['音质很清晰，降噪效果不错。但戴久了耳朵疼，打游戏声音慢半拍。', '降噪真厉害，开了之后地铁广播听得一清二楚，真是谢谢你。', '昨天戴着它开会，对方让我重复了三遍。回家听歌倒是很享受。', '安静办公室里降噪挺舒服，到了地铁上却完全压不住。'];
const mode = ref('hybrid'); const maxChars = computed(() => mode.value === 'semantic' ? 5000 : 1000); const result = ref<Analysis | null>(null); const chars = computed(() => Array.from(text.value).length);
watch(mode, () => { result.value = null; });
async function runAnalysis() { if (busy.value) return; busy.value = true; error.value = ''; try { result.value = await post<Analysis>('/analyze', { text: text.value, mode: mode.value }); } catch (e) { error.value = (e as Error).message; } finally { busy.value = false; } }
function sample(index: number) { text.value = examples[index]!; void runAnalysis(); }
const summary=ref<ProductSummary|null>(null); const productId = ref(''); const stats = ref<ProductStats | null>(null); const pure = ref(false);
const filters = ref({ aspect: '', sentiment: '', search: '', pending: false, corrected: false }); const reviews = ref<Review[]>([]); const page = ref(1); const total = ref(0); const loadingReviews = ref(false);
let reviewRequest = 0; let statsRequest = 0;
function reviewQuery() { return new URLSearchParams({ productId: productId.value, aspect: filters.value.aspect, sentiment: filters.value.sentiment, search: filters.value.search, pending: String(filters.value.pending), corrected: String(filters.value.corrected), pure: String(pure.value), page: String(page.value), size: '8' }).toString(); }
async function loadReviews() { const current = ++reviewRequest; loadingReviews.value = true; try { const data = await api<{ rows: Review[]; total: number }>(`/reviews?${reviewQuery()}`); if (current === reviewRequest) { reviews.value = data.rows; total.value = data.total; } } catch (e) { if (current === reviewRequest) error.value = (e as Error).message; } finally { if (current === reviewRequest) loadingReviews.value = false; } }
async function loadStats() { if (!productId.value) return; const current = ++statsRequest; try { const [data,points] = await Promise.all([api<ProductStats>(`/products/${productId.value}/stats?pure=${pure.value}`),api<ProductSummary>(`/products/${productId.value}/summary?pure=${pure.value}`)]); if (current === statsRequest) { stats.value = data; summary.value=points; } } catch (e) { error.value = (e as Error).message; } }
async function refreshed() { await Promise.all([loadReviews(), loadStats(), loadCompare()]); notice.value = '复核已保存，画像与对比已同步更新。'; }
watch([productId, pure], () => { page.value = 1; void loadStats(); void loadReviews(); });
watch(page, () => void loadReviews());
function applyFilters() { page.value = 1; void loadReviews(); }
function selectAspect(aspect: AspectId) { filters.value.aspect = filters.value.aspect === aspect ? '' : aspect; applyFilters(); }
const selectedProducts = ref<string[]>([]); const comparisons = ref<ProductStats[]>([]); const compareLoading = ref(false); const scenario = ref('all');
const scenarioAspects = computed<readonly string[]>(() => ({ all: ASPECTS.map(a => a.id), commute: ['noise','comfort'], game: ['latency','sound'], long: ['comfort','battery'] })[scenario.value] ?? []);
let compareRequest = 0;
async function loadCompare() { const current = ++compareRequest; if (selectedProducts.value.length < 2) { comparisons.value = []; return; } compareLoading.value = true; try { const data = await api<ProductStats[]>(`/compare?ids=${selectedProducts.value.join(',')}`); if (current === compareRequest) comparisons.value = data; } catch (e) { if (current === compareRequest) error.value = (e as Error).message; } finally { if (current === compareRequest) compareLoading.value = false; } }
watch(selectedProducts, () => void loadCompare(), { deep: true });
const loginForm = ref({ username: 'admin', password: '' }); const loginError = ref(''); const loginBusy = ref(false);
async function login() { loginBusy.value = true; loginError.value = ''; try { const data = await post<{ token: string }>('/auth/login', loginForm.value); saveToken(data.token); admin.value = true; loginForm.value.password = ''; await loadData(); } catch (e) { loginError.value = (e as Error).message; } finally { loginBusy.value = false; } }
async function logout() { try { await post('/auth/logout', {}); } finally { saveToken(null); admin.value = false; preview.value = null; jobs.value = []; batches.value = []; } }
const csv = ref('');
const importName = ref('评论导入.csv'); const importSource = ref(''); const isSynthetic = ref(false); const preview = ref<ImportPreview | null>(null); const importBusy = ref(false); const importError = ref('');
const columns = ref<ImportColumns | null>(null); const mapping = ref<ColumnMapping>({}); const fallbackProduct = ref(''); const encoding = ref('utf-8'); const batchMode = ref('semantic'); const fileBytes = ref<ArrayBuffer | null>(null);
const batches = ref<DataBatch[]>([]); const jobs = ref<Job[]>([]);
watch([csv, importSource, isSynthetic, importName, fallbackProduct, mapping], () => preview.value = null, { deep: true });
watch(csv, () => { columns.value = null; mapping.value = {}; });
watch(encoding, () => decodeFile());
function decodeFile() { if (!fileBytes.value) return; try { csv.value = new TextDecoder(encoding.value, { fatal: true }).decode(fileBytes.value); importError.value = ''; } catch { csv.value = ''; importError.value = '文件编码不匹配，请改选 UTF-8 或 GB18030 后重试'; } }
async function inspectColumns() { importError.value = ''; importBusy.value = true; try { columns.value = await post<ImportColumns>('/imports/columns', { csv: csv.value }); mapping.value = { ...columns.value.mapping }; } catch (e) { importError.value = (e as Error).message; } finally { importBusy.value = false; } }
async function refreshModel() { model.value = await api<typeof model.value>('/model'); if (model.value?.semantic.ready) { mode.value = 'semantic'; batchMode.value = 'semantic'; } }
const jobErrors = ref<Record<number, { reviewId: number; message: string }[]>>({});
async function loadJobErrors(jobId: number) { try { jobErrors.value[jobId] = await api(`/jobs/${jobId}/errors`); } catch (e) { error.value = (e as Error).message; } }
async function readFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (file.size > 5 * 1024 * 1024) { importError.value = '文件不能超过 5 MB'; return; } fileBytes.value = await file.arrayBuffer(); importName.value = file.name; decodeFile(); if (csv.value) await inspectColumns(); }
async function previewImport() { importBusy.value = true; importError.value = ''; try { preview.value = await post<ImportPreview>('/imports/preview', { csv: csv.value, name: importName.value, source: importSource.value, isSynthetic: isSynthetic.value, ...(columns.value ? { mapping: mapping.value } : {}), productId: fallbackProduct.value }); } catch (e) { importError.value = (e as Error).message; } finally { importBusy.value = false; } }
async function commitImport() { if (!preview.value) return; importBusy.value = true; importError.value = ''; try { const selected=preview.value.rows.find(r=>r.valid&&!r.duplicate)?.productId; const data = await post<{ batchId: number; inserted: number }>('/imports/commit', { token: preview.value.token }); if(selected)productId.value=selected; preview.value = null; notice.value = `已保存 ${data.inserted} 条评论。`; products.value = await api<Product[]>('/products'); await loadData(); await post('/jobs', { batchId: data.batchId, mode: batchMode.value }); notice.value = `已导入 ${data.inserted} 条评论，分析任务已创建。`; products.value = await api<Product[]>('/products'); await loadData(); } catch (e) { importError.value = (e as Error).message; } finally { importBusy.value = false; } }
async function loadData() { if (!admin.value) return; try { const [b, j] = await Promise.all([api<typeof batches.value>('/batches'), api<Job[]>('/jobs')]); batches.value = b; jobs.value = j; } catch (e) { error.value = (e as Error).message; } }
async function analyzeBatch(batchId: number) { try { await post('/jobs', { batchId, mode: batchMode.value }); await loadData(); } catch (e) { error.value = (e as Error).message; } }
async function exportReviews() { try { await download(`/export?${reviewQuery()}`, '耳机评论分析结果.csv'); } catch (e) { error.value = (e as Error).message; } }
function templateDownload() { const blob = new Blob(['\uFEFFproductId,reviewId,text,source\nqingxing,example-001,"音质很好，但戴久了耳朵疼。",人工编写合成示例\n'], { type: 'text/csv;charset=utf-8' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = '评论导入模板.csv'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
const addProductOpen = ref(false); const editingProduct = ref(false); const productForm = ref({ id: '', name: '', subtitle: '' }); const productError = ref('');
function editProduct(p?: Product) { editingProduct.value = !!p; productForm.value = p ? { id: p.id, name: p.name, subtitle: p.subtitle } : { id: '', name: '', subtitle: '' }; addProductOpen.value = true; productError.value = ''; }
async function addProduct() { productError.value = ''; try { products.value = editingProduct.value ? await api<Product[]>(`/products/${productForm.value.id}`, { method: 'PATCH', body: JSON.stringify(productForm.value) }) : await post<Product[]>('/products', productForm.value); addProductOpen.value = false; productForm.value = { id: '', name: '', subtitle: '' }; notice.value = '产品已保存，可以使用对应 ID 导入评论。'; } catch (e) { productError.value = (e as Error).message; } }
async function useCollection(data:{csv:string;productId:string;url:string;platform:string}) { csv.value=data.csv;fileBytes.value=null;encoding.value='utf-8';fallbackProduct.value=data.productId;importSource.value=data.url;isSynthetic.value=false;importName.value='平台评论.csv';await router.push('/data');await inspectColumns();notice.value='采集结果已载入，请核对列映射与耳机，再预览导入。'; }
let poll: ReturnType<typeof setInterval>;
onMounted(async () => {
  try { const [p, m] = await Promise.all([api<Product[]>('/products'), api<typeof model.value>('/model')]); products.value = p; model.value = m; if (m?.semantic.ready) { mode.value = 'semantic'; batchMode.value = 'semantic'; } productId.value = p.find(v=>v.source==='用户创建')?.id ?? p[0]?.id ?? ''; selectedProducts.value = p.slice(0, 2).map(v => v.id); if (token()) { try { await api('/auth/me'); admin.value = true; await loadData(); } catch { saveToken(null); } } if(path.value==='/try')await runAnalysis(); }
  catch (e) { error.value = `无法连接分析服务：${(e as Error).message}。请检查后端是否启动。`; }
  poll = setInterval(() => { if (admin.value && path.value === '/data') void loadData(); }, 2000);
});
onUnmounted(() => clearInterval(poll));
watch(path, () => { error.value = ''; notice.value = ''; if (path.value === '/products') { void loadStats(); void loadReviews(); } if (path.value === '/compare') void loadCompare(); if (path.value === '/data') void loadData(); if(path.value==='/')void loadStats(); if(path.value==='/try'&&!result.value)void runAnalysis(); });
</script>

<template>
  <div class="app-shell">
    <header class="site-header"><div class="header-inner"><RouterLink to="/" class="brand"><span class="brand-icon"><Headphones :size="22"/></span><span>听见<span class="brand-description">耳机评论分析</span></span></RouterLink><nav aria-label="主导航"><RouterLink to="/">评价总览</RouterLink><RouterLink to="/products">产品画像</RouterLink><RouterLink to="/compare">产品对比</RouterLink><RouterLink to="/data">评论导入</RouterLink><RouterLink to="/collect">平台采集</RouterLink></nav><span class="header-status"><span class="status-dot"/>{{ model ? '本地分析服务' : '连接服务中' }}</span></div></header>
    <main>
      <div v-if="error" class="message error" role="alert"><Info :size="17"/><span>{{ error }}</span><button @click="error = ''" aria-label="关闭错误">关闭</button></div>
      <div v-if="notice" class="message success" role="status"><Check :size="17"/><span>{{ notice }}</span><button @click="notice = ''" aria-label="关闭提示">关闭</button></div>

      <template v-if="path === '/'"><ProductOverview :products="products" :product-id="productId" :stats="stats" :summary="summary" :ready="!!model?.semantic.ready" @select="productId=$event" @refresh="loadStats"/></template>
      <template v-else-if="path === '/collect'"><PlatformCollection :products="products" :admin="admin" @use="useCollection" @products="products=$event"/></template>
      <template v-else-if="path === '/try'">
        <div class="page-heading"><div><h1>从评论中，看见每个方面的评价。</h1><p>识别音质、降噪、舒适度等六项评价，判断情感，并回到原文核对。</p></div><span class="quiet-label"><MessageSquareText :size="16"/>方面级情感分析</span></div>
        <div class="analysis-layout">
          <section class="panel input-panel"><div class="panel-title"><h2>输入一条评论</h2><span class="subtle">中文文本</span></div><label class="sr-only" for="review-input">耳机评论</label><textarea id="review-input" v-model="text" class="comment-input" placeholder="例如：音质不错，但戴久了耳朵疼。" :maxlength="10000" :disabled="busy"/><div class="input-meta"><span>不会写入产品统计</span><span :class="{ 'error-text': chars > maxChars }">{{ chars }} / {{ maxChars }} 字</span></div><label class="model-choice">分析方法<select v-model="mode" :disabled="busy"><option value="semantic">本地文本模型（复杂语义）</option><option value="hybrid">朴素贝叶斯 + 规则（基线）</option><option value="rules">仅领域规则（对照）</option></select></label><button class="primary analyze-button" :disabled="busy || !text.trim() || chars > maxChars" @click="runAnalysis"><LoaderCircle v-if="busy" :size="18" class="spin"/><template v-else><span>分析评论</span><ArrowRight :size="18"/></template><span v-if="busy">正在分析…</span></button><div class="sample-area"><h3>试试不同的表达</h3><div class="sample-buttons"><button @click="sample(0)" :disabled="busy">多方面评价</button><button @click="sample(1)" :disabled="busy">反讽表达</button><button @click="sample(2)" :disabled="busy">隐含评价</button><button @click="sample(3)" :disabled="busy">情境差异</button></div><p class="subtle">示例由人工编写，用于演示分析流程。</p></div></section>
          <AnalysisResult :result="result" :busy="busy"/>
        </div>
        <p v-if="model && !model.semantic.ready" class="inline-note warning">{{ model.semantic.message }}。语义模型部署步骤见数据工作台。</p><section class="method-section"><button class="method-toggle" @click="modelExpanded = !modelExpanded" :aria-expanded="modelExpanded"><SlidersHorizontal :size="17"/><span>分析方法与能力边界</span><span>{{ modelExpanded ? '收起' : '展开' }}</span></button><div v-if="modelExpanded && model" class="method-content"><p>{{ model.algorithm }}；{{ model.trainingExamples }} 条{{ model.dataKind }}。这是基线对照。语义模式使用本地文本模型读取完整上下文并抽取方面、情感和原文证据，再由服务器验证证据。未涉及的方面不会被填补。</p><ul><li v-for="item in model.limitations" :key="item">{{ item }}</li></ul><div v-if="model.evaluation" class="evaluation-inline"><strong>基线样例测试集验证</strong><span>{{ model.evaluation.count }} 条独立编写样例 · 端到端 F1 {{ (model.evaluation.hybrid.pairMicroF1 * 100).toFixed(1) }}%</span><span>该结果仅反映人工编写测试样例，不代表真实评论效果。</span></div></div></section>
      </template>

      <template v-else-if="path === '/products'">
        <div class="page-heading"><div><h1>产品评价画像</h1><p>把评论整理成六项评价，查看分布，再核对具体原文。</p></div><label class="select-inline">查看产品<select v-model="productId" aria-label="查看产品"><option v-for="p in products" :value="p.id" :key="p.id">{{ p.name }}</option></select></label></div>
        <template v-if="stats">
          <div class="product-summary"><div><h2>{{ stats.product.name }}</h2><p>{{ stats.product.subtitle }}</p></div><div class="summary-count"><strong>{{ stats.reviews }}</strong><span>条评论 · {{ stats.analyzed }} 条已分析</span></div></div>
          <div class="data-note"><Info :size="16"/><span><span v-if="stats.synthetic">包含 {{ stats.synthetic }} 条合成示例。</span>正面占比 = 正面 / 已判定评论；未提及与待复核不进入分母。少于 20 条提示样本不足。当前统计使用每条评论最近一次成功分析，可能包含不同方法。</span></div>
          <div class="distribution-header"><h2>各方面评价分布</h2><label class="checkbox-label"><input type="checkbox" v-model="pure"/>只看原始模型结果</label></div>
          <section class="panel distribution-panel"><button v-for="stat in stats.aspects" :key="stat.aspect" class="distribution-row" :class="{ selected: filters.aspect === stat.aspect }" @click="selectAspect(stat.aspect)"><span class="distribution-name">{{ ASPECTS.find(a => a.id === stat.aspect)?.name }}</span><div class="distribution-data"><div class="stacked-bar" :aria-label="`正面 ${stat.positive}，负面 ${stat.negative}，中性 ${stat.neutral}，混合 ${stat.mixed}`"><span v-for="s in (['positive','negative','neutral','mixed'] as const)" :key="s" :class="s" :style="{ width: `${stat.total ? stat[s] / stat.total * 100 : 0}%` }"/></div><span class="distribution-caption">正面 {{ stat.positive }} · 负面 {{ stat.negative }} · 中性 {{ stat.neutral }} · 混合 {{ stat.mixed }}<template v-if="stat.pending"> · 待复核 {{ stat.pending }}</template></span></div><span class="ratio">{{ stat.positiveRatio === null ? '—' : `${stat.positiveRatio}%` }}<small>正面占比</small></span><span class="sample-size">{{ stat.total }} 条已判定<small>{{ stat.total < 20 ? '样本不足' : `已复核 ${stat.corrected} 条` }}</small></span></button></section>
          <div class="section-heading"><h2>评论与原文依据 <span class="subtle">{{ total }} 条</span></h2><button v-if="admin" class="secondary small" @click="exportReviews"><Download :size="15"/>导出筛选结果</button></div>
          <form class="review-filters" @submit.prevent="applyFilters"><label>评价方面<select v-model="filters.aspect" @change="applyFilters"><option value="">全部方面</option><option v-for="a in ASPECTS" :value="a.id" :key="a.id">{{ a.name }}</option></select></label><label>情感<select v-model="filters.sentiment" @change="applyFilters"><option value="">全部情感</option><option v-for="(name, s) in SENTIMENT_NAMES" :value="s" :key="s">{{ name }}</option></select></label><label class="search-label">原文关键词<input v-model="filters.search" placeholder="搜索评论原文"/></label><button class="secondary" type="submit">筛选</button><label class="checkbox-label"><input type="checkbox" v-model="filters.pending" @change="applyFilters"/>待复核</label><label class="checkbox-label"><input type="checkbox" v-model="filters.corrected" @change="applyFilters"/>已复核</label></form>
          <section class="panel review-panel" :aria-busy="loadingReviews"><ReviewList :reviews="reviews" :admin="admin" @updated="refreshed"/></section><div class="pagination"><span>第 {{ page }} 页 · 共 {{ total }} 条</span><button class="secondary small" :disabled="page <= 1" @click="page--">上一页</button><button class="secondary small" :disabled="page * 8 >= total" @click="page++">下一页</button></div>
        </template><div v-else class="empty-state">正在加载产品评价…</div>
      </template>

      <template v-else-if="path === '/compare'">
        <div class="page-heading"><div><h1>按你的需求，对比评价。</h1><p>选择两到三款耳机，对比相同方面的评价分布与原文依据。</p></div></div>
        <section class="compare-controls panel"><div class="product-options"><label v-for="p in products" :key="p.id" class="product-option" :class="{ chosen: selectedProducts.includes(p.id) }"><input type="checkbox" :value="p.id" v-model="selectedProducts" :disabled="selectedProducts.length >= 3 && !selectedProducts.includes(p.id)"/><span><strong>{{ p.name }}</strong><small>{{ p.subtitle }}</small></span></label></div><div class="scenario-options"><span>关注什么？</span><button v-for="(name, key) in { all: '全部方面', commute: '通勤', game: '游戏', long: '长时间佩戴' }" :key="key" :class="{ active: scenario === key }" @click="scenario = key">{{ name }}</button></div></section>
        <div class="data-note"><Info :size="16"/><span>需求预设只突出相关维度。比较结果来自评论，不是耳机性能测评；不会生成缺乏证据的总排名。</span></div>
        <div v-if="selectedProducts.length < 2" class="empty-state">请至少选择两款产品。</div><div v-else-if="compareLoading" class="empty-state">正在获取对比数据…</div>
        <section v-else class="comparison-grid" :style="{ '--product-count': comparisons.length }"><div class="comparison-label column-head">评价方面</div><div v-for="p in comparisons" :key="p.product.id" class="column-head"><h2>{{ p.product.name }}</h2><span>{{ p.reviews }} 条评论<span v-if="p.synthetic"> · {{ p.synthetic }} 条合成示例</span></span></div><template v-for="a in ASPECTS.filter(a => scenarioAspects.includes(a.id))" :key="a.id"><div class="comparison-label"><strong>{{ a.name }}</strong><small>{{ a.description }}</small></div><div v-for="p in comparisons" :key="p.product.id" class="comparison-cell"><template v-for="stat in p.aspects.filter(s => s.aspect === a.id)" :key="stat.aspect"><div class="compare-ratio"><strong>{{ stat.positiveRatio === null ? '暂无证据' : `${stat.positiveRatio}%` }}</strong><span v-if="stat.positiveRatio !== null">正面占比</span></div><div class="stacked-bar"><span v-for="s in (['positive','negative','neutral','mixed'] as const)" :key="s" :class="s" :style="{ width: `${stat.total ? stat[s] / stat.total * 100 : 0}%` }"/></div><p class="subtle">已判定 {{ stat.total }} 条 · 负面 {{ stat.negative }} 条<template v-if="stat.pending"> · 待复核 {{ stat.pending }} 条</template></p><span v-if="stat.total < 20" class="sample-warning">样本不足</span><details v-if="stat.examples.length" class="compare-evidence"><summary>查看原文依据</summary><p v-for="r in stat.examples" :key="r.id">{{ r.opinions.find(o => o.aspect === a.id)?.evidence.map(e => e.text).join('；') }}<small>{{ r.isSynthetic ? '合成示例' : r.source }}</small></p></details></template></div></template></section>
      </template>

      <template v-else-if="path === '/data'">
        <div class="page-heading"><div><h1>导入一款耳机的评论</h1><p>选择耳机、上传 CSV，再用本地模型批量分析。</p></div><button v-if="admin" class="secondary small" @click="logout"><LogOut :size="15"/>退出登录</button></div>
        <section class="model-status-line"><span>{{ model?.semantic.ready ? '本地模型已连接，可批量分析评论' : '本地模型未连接：可以导入，连接后再开始分析' }}</span><button class="text-button" @click="refreshModel().catch(e => error = e.message)">检查模型连接</button></section><form v-if="!admin" class="panel login-panel" @submit.prevent="login"><h2>登录后管理评论</h2><p class="subtle">登录后可以导入、采集、复核和导出评论。当前为本机账户。</p><label>账号<input v-model="loginForm.username" autocomplete="username" required/></label><label>密码<input v-model="loginForm.password" type="password" autocomplete="current-password" required/></label><p v-if="loginError" class="error-text" role="alert">{{ loginError }}</p><button class="primary" :disabled="loginBusy">{{ loginBusy ? '登录中…' : '登录工作台' }}</button><p class="login-help">首次运行密码保存在项目的 <code>data/runtime/admin-password.txt</code>。也可在首次启动前设置 ADMIN_PASSWORD。</p></form>
        <template v-else>
          <div class="section-heading"><h2>产品管理</h2><button class="secondary small" @click="addProductOpen ? addProductOpen = false : editProduct()">{{ addProductOpen ? '收起' : '添加产品' }}</button></div><section class="panel"><div v-for="p in products" :key="p.id" class="batch-row"><div><strong>{{ p.name }}</strong><span class="subtle">{{ p.subtitle }}</span></div><code>{{ p.id }}</code><span>{{ p.count }} 条评论</span><button class="text-button" @click="editProduct(p)">编辑</button></div><form v-if="addProductOpen" class="add-product-form" @submit.prevent="addProduct"><div class="form-grid"><label>产品 ID<input v-model="productForm.id" required :disabled="editingProduct" pattern="[a-z0-9][a-z0-9_-]*" placeholder="例如：my-earphone"/></label><label>产品名称<input v-model="productForm.name" required maxlength="80"/></label></div><label>产品说明<input v-model="productForm.subtitle" maxlength="120"/></label><p v-if="productError" role="alert" class="error-text">{{ productError }}</p><button class="primary small">保存产品</button></form></section>
          <section class="panel import-panel"><div class="panel-title"><h2>导入评论</h2><button class="text-button" @click="templateDownload"><Download :size="15"/>下载 CSV 模板</button></div><p class="subtle">支持原始列名映射，只需评论正文；编号可自动生成，产品可统一指定。最多 5,000 条、每条 5,000 字、文件 5 MB。</p><div class="import-layout"><div><label class="file-picker"><Upload :size="18"/><span>选择 CSV 文件</span><input type="file" accept=".csv,text/csv" @change="readFile"/></label><label>文件编码<select v-model="encoding"><option value="utf-8">UTF-8（推荐）</option><option value="gb18030">GB18030 / GBK</option></select></label><label>或粘贴 CSV 内容<textarea v-model="csv" class="csv-input" spellcheck="false"/></label><button class="text-button" :disabled="importBusy || !csv.trim()" @click="inspectColumns">识别列与设置映射</button><ImportMapping v-if="columns" :columns="columns" v-model="mapping"/></div><div class="import-settings"><label>统一导入产品 / 集合<select v-model="fallbackProduct" aria-label="统一导入产品 / 集合"><option value="">使用文件中的产品 ID</option><option v-for="p in products" :key="p.id" :value="p.id">{{ p.name }}</option></select></label><p class="subtle">文件没有产品编号时，先在上方创建对应耳机，再选择它。请核对评论所属商品。</p><label>批次分析方法<select v-model="batchMode" aria-label="批次分析方法"><option value="semantic">本地文本模型（复杂语义）</option><option value="hybrid">朴素贝叶斯 + 规则（基线对照）</option></select></label><label>批次名称<input v-model="importName" maxlength="120"/></label><label>数据来源与使用说明<input v-model="importSource" maxlength="200" placeholder="说明数据来自哪里，以及是否允许使用"/></label><label class="checkbox-label"><input type="checkbox" v-model="isSynthetic"/>这些是人工合成数据</label><p class="subtle">取消勾选前，请确认是有使用权限的真实数据。该标记随评论保存。</p><button class="primary" :disabled="importBusy || !csv.trim() || !importSource.trim()" @click="previewImport"><FileText :size="16"/>{{ importBusy ? '处理中…' : '校验并预览' }}</button></div></div><p v-if="importError" class="error-text" role="alert">{{ importError }}</p><div v-if="preview" class="import-preview"><div class="preview-heading"><span><strong>{{ preview.valid }}</strong> 条可导入 · {{ preview.invalid }} 条错误 · {{ preview.duplicates }} 条重复</span><button class="primary small" :disabled="importBusy || !preview.valid" @click="commitImport">导入并开始分析<ArrowRight :size="15"/></button></div><div class="table-scroll"><table><thead><tr><th>行号</th><th>产品 ID</th><th>评论</th><th>校验结果</th></tr></thead><tbody><tr v-for="row in preview.rows.slice(0, 50)" :key="row.row"><td>{{ row.row }}</td><td>{{ row.productId }}</td><td>{{ row.text }}</td><td :class="{ 'error-text': !row.valid }">{{ row.errors.length ? row.errors.join('；') : row.duplicate ? '重复，跳过' : '有效' }}</td></tr></tbody></table></div><p v-if="preview.rows.length > 50" class="subtle">显示前 50 行；提交将处理全部 {{ preview.rows.length }} 行中的有效非重复评论。</p></div></section>
          <div class="section-heading"><h2>分析任务</h2><RouterLink to="/" class="text-button">查看分析总览<ArrowRight :size="15"/></RouterLink><button class="text-button" @click="loadData"><RefreshCw :size="15"/>刷新</button></div><AnalysisTasks :jobs="jobs" :batches="batches" :errors="jobErrors" @retry="analyzeBatch" @errors="loadJobErrors"/>
          <div class="section-heading"><h2>数据批次</h2><span class="subtle">{{ batches.length }} 个批次</span></div><section class="panel batch-list"><article v-for="batch in batches" :key="batch.id" class="data-batch"><div class="batch-information"><h3>{{ batch.name }}</h3><p class="batch-products">{{ batch.products?.map(p=>`${p.name}（${p.count} 条）`).join('、') || '评论数据' }}</p><p class="subtle">批次 #{{ batch.id }} · {{ batch.source }}</p><p v-if="batch.summary?.submitted" class="subtle">提交 {{ batch.summary.submitted }} 条 · 错误 {{ batch.summary.invalid ?? 0 }} 条 · 重复 {{ batch.summary.duplicates ?? 0 }} 条</p></div><div class="batch-action"><span>{{ batch.count }} 条已保存</span><button class="secondary small" @click="analyzeBatch(batch.id)">分析该批次</button></div></article><p v-if="!batches.length" class="empty-state compact">暂无数据批次</p></section>

        </template>
      </template>
    </main>
    <footer><RouterLink to="/try">单条分析试用</RouterLink><span>听见 · 让评价回到原文</span><span>本地处理 · 原文可追溯</span></footer>
  </div>
</template>